"use strict";
const Q=new URLSearchParams(location.search),preview=Q.get('preview')==='1',monitor=Q.get('monitor')==='1';
const el=id=>document.getElementById(id),escapeText=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let currentId=null,expiresTimer=0,busy=false,settings={showImage:true};
async function json(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(r.status);return r.json();}
function hide(){el('alert').hidden=true;currentId=null;clearTimeout(expiresTimer);}
function show(event,serverTime){if(!event){hide();return;}const remaining=Math.max(0,event.expires-serverTime);if(!remaining){hide();return;}if(currentId===event.id)return;currentId=event.id;clearTimeout(expiresTimer);el('alert').hidden=true;
 el('alertEyebrow').textContent=event.kind==='test'?'DESIGNVORSCHAU / TESTFUND':event.kind==='mission-accepted'?'AUFTRAG ANGENOMMEN':event.kind==='mission-brief'?'AUFTRAGSINFORMATIONEN':event.kind==='mission-details'?'AUFTRAG UND BAUPLAN':event.kind==='mission'?'DEIN NÄCHSTER AUFTRAG':event.kind==='manual'?'DEIN BAUPLANARCHIV':'SAMMLUNG ERWEITERT';
 el('alertTitle').textContent=event.title||(event.items.length===1?'Neuer Bauplan erhalten':'Neue Baupläne erhalten');el('alertCount').textContent=event.items.length+(event.items.length===1?' Bauplan':' Baupläne');
 el('alertItems').classList.toggle('single',event.items.length===1);
 el('alertItems').innerHTML=['mission-details','mission-brief'].includes(event.kind)?ObsMissionDetails.render(event.items[0],event.kind==='mission-brief'):event.items.map(i=>ObsBlueprintCards.render(i,event.items.length===1&&event.kind!=='mission')).join('');
 ObsBlueprintCards.rotate();el('alert').dataset.kind=event.kind;el('alertCount').hidden=['mission-accepted','mission-details','mission-brief'].includes(event.kind);el('alert').hidden=false;const bar=el('alertTimer');bar.style.transition='none';bar.style.width=(remaining/(event.expires-event.started)*100)+'%';requestAnimationFrame(()=>requestAnimationFrame(()=>{bar.style.transition=`width ${remaining}s linear`;bar.style.width='0%';}));expiresTimer=setTimeout(hide,remaining*1000);if(['mission-details','mission-brief','manual'].includes(event.kind)){const box=el('alertItems'),id=currentId;box.scrollTop=0;const start=performance.now()+1500;const scroll=now=>{if(currentId!==id)return;box.scrollTop=Math.max(0,Math.min(1,(now-start)/Math.max(1000,(remaining-3)*1000)))*(box.scrollHeight-box.clientHeight);if(now<start+remaining*1000)requestAnimationFrame(scroll);};requestAnimationFrame(scroll);}
}
async function poll(){if(busy)return;busy=true;try{const [cfg,data]=await Promise.all([json('/api/obs'),json('/api/obs/alerts'+(monitor?'':'?consume=1'))]);settings={...cfg.settings,imageIntervalSeconds:cfg.alerts.imageIntervalSeconds};document.body.dataset.motion=settings.animations===false?'off':'on';document.body.dataset.theme=settings.theme;document.body.dataset.position=settings.position;show(data.event,data.serverTime);}catch{/* A running alert still expires locally during a NAS/network outage. */}finally{busy=false;}}
async function demo(){try{const [cfg,catalog]=await Promise.all([json('/api/obs'),json('/api/catalog')]);settings={...cfg.settings,imageIntervalSeconds:cfg.alerts.imageIntervalSeconds};document.body.dataset.motion=settings.animations===false?'off':'on';document.body.dataset.theme=Q.get('theme')||settings.theme;document.body.dataset.position=settings.position;const items=catalog.items.filter(i=>i.isDone).slice(0,3);await Promise.all(items.map(async i=>{const d=await json('/api/dossier/'+i.id);i.images=d.data?.images||[];}));const start=Date.now()/1000;show({id:'preview',kind:'test',items,started:start,expires:start+cfg.alerts.durationSeconds},start);}catch{hide();}}
if(preview)void demo();else{void poll();setInterval(poll,1000);}
